'use strict';
const $=id=>document.getElementById(id), clone=x=>JSON.parse(JSON.stringify(x));
const S={config:null,file:null,job:null,boxes:[],selected:-1,tool:'pan',image:null,scale:1,ox:0,oy:0,drag:null,history:[],dirty:false,busy:false,page:1,includedIds:[]};
const canvas=$('canvas'),ctx=canvas.getContext('2d');
function canAsk(){return !S.config?.replay&&!S.busy&&!!(S.file||S.sample||S.reuseJobId)&&S.validated!==false&&!!$('question').value.trim()}
function updateAskState(){$('run').disabled=!canAsk()}
function status(text,error=false){$('status').textContent=text;$('status').classList.toggle('error',error)}
async function api(path,body){const response=await fetch(path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-ProofPlan-Token':S.config.token,...(path==='/api/jobs'?{'Idempotency-Key':S.requestKey}: {})},body:JSON.stringify(body)});let data;try{data=await response.json()}catch(_){const e=Error(response.status===401?'Session expired. Reload and enter the access code.':`Server returned an invalid response (HTTP ${response.status}). ${path==='/api/jobs'?'Submission may have been accepted; use Reconnect to check the same request.':'Please retry.'}`);e.httpStatus=response.status;throw e}if(!response.ok){const e=Error(data.error||'Request failed');e.httpStatus=response.status;throw e}return data}
function exportState(){const ready=S.job?.status==='success'&&!S.dirty;for(const id of ['exportDiagnostic','exportJson','exportPng']){$(id).classList.toggle('disabled',!ready);$(id).setAttribute('aria-disabled',String(!ready));if(!ready)$(id).removeAttribute('href');else $(id).href=`/api/jobs/${S.job.id}/${id==='exportDiagnostic'?'diagnostic.zip':id==='exportJson'?'export.json':'export.png?page='+S.page}`;if(id==='exportDiagnostic'&&S.config?.replay){$(id).hidden=true;$(id).removeAttribute('href')}}$('saveReview').disabled=!S.job||S.busy;updateAskState();$('saveState').textContent=S.dirty?'Unsaved review edits':S.job?.review?.reviewed?`Review revision ${S.job.review.revision} saved`:'Model output · not reviewed'}
function snapshot(){S.history.push(clone({boxes:S.boxes,includedIds:S.includedIds}));if(S.history.length>50)S.history.shift()}
function changed(){S.dirty=true;refresh()}
function selectTool(tool){if(S.config?.replay)tool='pan';S.tool=tool;for(const [id,t] of [['panTool','pan'],['selectTool','select'],['addTool','add']])$(id).classList.toggle('active',tool===t);canvas.style.cursor=tool==='pan'?'grab':tool==='add'?'crosshair':'default'}
function point(e){const r=canvas.getBoundingClientRect();return [(e.clientX-r.left-S.ox)/S.scale,(e.clientY-r.top-S.oy)/S.scale]}
function clampPoint(p){return [Math.max(0,Math.min(S.image.width,p[0])),Math.max(0,Math.min(S.image.height,p[1]))]}
function fit(){if(S.job?.input_kind==='ifc'&&window.IFCView){window.IFCView.fit();return}if(!S.image)return;const r=canvas.getBoundingClientRect();S.scale=Math.min((r.width-36)/S.image.width,(r.height-36)/S.image.height);S.ox=(r.width-S.image.width*S.scale)/2;S.oy=(r.height-S.image.height*S.scale)/2;draw()}
function zoom(factor,cx,cy){if(S.job?.input_kind==='ifc'&&window.IFCView){window.IFCView.zoom(factor);return}if(!S.image)return;const r=canvas.getBoundingClientRect();cx??=r.width/2;cy??=r.height/2;const x=(cx-S.ox)/S.scale,y=(cy-S.oy)/S.scale;S.scale=Math.min(12,Math.max(.02,S.scale*factor));S.ox=cx-x*S.scale;S.oy=cy-y*S.scale;draw()}
function draw(){const r=canvas.getBoundingClientRect(),dpr=devicePixelRatio||1;if(canvas.width!==Math.round(r.width*dpr)||canvas.height!==Math.round(r.height*dpr)){canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,r.width,r.height);if(!S.image)return;ctx.translate(S.ox,S.oy);ctx.scale(S.scale,S.scale);ctx.drawImage(S.image,0,0);$('zoomLabel').textContent=`${Math.round(S.scale*100)}%`;if(S.overlay===false)return;let n=0;for(let i=0;i<S.boxes.length;i++){const b=S.boxes[i],[x1,y1,x2,y2]=b.xyxy;if(b.included)n++;if((b.page||1)!==S.page)continue;const selected=i===S.selected,cited=hybridCitesEvidence(b.evidence_id);ctx.strokeStyle=selected?'#f000b8':cited?'#d56700':b.included?['#007f9e','#da6900','#557c00'][i%3]:'#6f7780';ctx.fillStyle=selected?'#ff00c826':'#00d9ff18';ctx.lineWidth=(selected?2.8:cited?2:1.4)/S.scale;ctx.setLineDash(b.included?[]:[4/S.scale,3/S.scale]);ctx.fillRect(x1,y1,x2-x1,y2-y1);ctx.strokeRect(x1,y1,x2-x1,y2-y1);ctx.setLineDash([]);const label=b.context_only?'Overview':b.included?String(n):'−';ctx.font=`${10/S.scale}px system-ui`;const tw=ctx.measureText(label).width,yy=Math.max(0,y1-12/S.scale);ctx.fillStyle=selected?'#f000b8':'#007f9e';ctx.fillRect(x1,yy,tw+5/S.scale,12/S.scale);ctx.fillStyle='white';ctx.fillText(label,x1+2/S.scale,yy+9/S.scale);if(selected&&!S.config?.replay){for(const [x,y]of[[x1,y1],[x2,y1],[x1,y2],[x2,y2]]){ctx.fillStyle='white';ctx.fillRect(x-3/S.scale,y-3/S.scale,6/S.scale,6/S.scale);ctx.strokeRect(x-3/S.scale,y-3/S.scale,6/S.scale,6/S.scale)}}}if(S.drag?.type==='add'){const a=S.drag.start,b=S.drag.last||a;ctx.strokeStyle='#f000b8';ctx.lineWidth=2/S.scale;ctx.strokeRect(a[0],a[1],b[0]-a[0],b[1]-a[1])}}
function refresh(){draw();drawCrop();const list=$('boxList');list.replaceChildren();let n=0;for(let i=0;i<S.boxes.length;i++){const b=S.boxes[i];if(b.included)n++;const row=document.createElement('div');row.className='box-row'+(i===S.selected?' selected':'');const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.disabled=!!S.config?.replay;checkbox.checked=b.included;checkbox.setAttribute('aria-label',`Include box ${i+1}`);checkbox.onclick=e=>e.stopPropagation();checkbox.onchange=()=>{snapshot();b.included=checkbox.checked;if(b.evidence_id){S.includedIds=S.includedIds.filter(id=>id!==b.evidence_id);if(b.included)S.includedIds.push(b.evidence_id)}changed()};const label=document.createElement('span');label.textContent=(b.included?`#${n}`:'Excluded')+` · ${b.class_name||'evidence'} · page ${b.page||1}`;const del=document.createElement('button');del.textContent='×';del.onclick=e=>{e.stopPropagation();S.selected=i;deleteSelected()};row.append(checkbox,label,del);row.onclick=()=>focusEvidence(i);list.append(row)}const count=S.job?.input_kind==='ifc'?S.includedIds.length:S.boxes.filter(b=>b.included).length;const instance=S.job?.review.instance_count;$('reviewCount').textContent=S.job?(instance?count:$('manualAnswer').value||displayValue(S.job.review.answer,S.job.review.unit)):'—';$('boxCount').textContent=S.boxes.filter(b=>b.included).length;$('manualAnswer').disabled=!!instance;if(!S.boxes.length)list.textContent=S.job?'No spatial boxes for this answer. Inspect evidence and limitations; add manual evidence if appropriate.':'Spatial evidence appears here.';evidenceTable();exportState()}

function deleteSelected(){if(S.config?.replay)return;if(S.selected<0||S.selected>=S.boxes.length)return;snapshot();const removed=S.boxes.splice(S.selected,1)[0];if(removed.evidence_id)S.includedIds=S.includedIds.filter(id=>id!==removed.evidence_id);S.selected=-1;changed()}
canvas.addEventListener('pointerdown',e=>{if(!S.image||S.busy||S.job?.input_kind==='ifc')return;canvas.setPointerCapture(e.pointerId);const p=clampPoint(point(e));if(S.tool==='pan'){S.drag={type:'pan',screen:[e.clientX,e.clientY],offset:[S.ox,S.oy]};return}if(!S.job)return;if(S.tool==='add'){S.drag={type:'add',start:p};return}if(S.selected>=0&&(S.boxes[S.selected].page||1)===S.page){const b=S.boxes[S.selected],[x1,y1,x2,y2]=b.xyxy;const corners=[[x1,y1],[x2,y1],[x1,y2],[x2,y2]];const hit=corners.findIndex(c=>Math.hypot((p[0]-c[0])*S.scale,(p[1]-c[1])*S.scale)<12);if(hit>=0){snapshot();S.drag={type:'resize',anchor:corners[3-hit],start:p};return}}const i=S.boxes.findLastIndex(b=>(b.page||1)===S.page&&p[0]>=b.xyxy[0]&&p[0]<=b.xyxy[2]&&p[1]>=b.xyxy[1]&&p[1]<=b.xyxy[3]);S.selected=i;if(i>=0){snapshot();S.drag={type:'move',start:p,original:clone(S.boxes[i].xyxy)}}refresh()});
canvas.addEventListener('pointermove',e=>{const drag=S.drag;if(!drag)return;if(drag.type==='pan'){S.ox=drag.offset[0]+e.clientX-drag.screen[0];S.oy=drag.offset[1]+e.clientY-drag.screen[1];draw();return}const p=clampPoint(point(e));if(drag.type==='add'){drag.last=p;draw();return}const b=S.boxes[S.selected];if(!b)return;if(drag.type==='resize'){const a=drag.anchor;b.xyxy=[Math.min(a[0],p[0]),Math.min(a[1],p[1]),Math.max(a[0],p[0]),Math.max(a[1],p[1])]}else{const a=drag.original;const dx=Math.max(-a[0],Math.min(S.image.width-a[2],p[0]-drag.start[0])),dy=Math.max(-a[1],Math.min(S.image.height-a[3],p[1]-drag.start[1]));b.xyxy=[a[0]+dx,a[1]+dy,a[2]+dx,a[3]+dy]}b.detector_score=null;S.dirty=true;draw()});
function finishDrag(){const drag=S.drag;if(!drag)return;if(drag.type==='add'&&drag.last){const [a,b]=[drag.start,drag.last],coords=[Math.min(a[0],b[0]),Math.min(a[1],b[1]),Math.max(a[0],b[0]),Math.max(a[1],b[1])];if(coords[2]-coords[0]>1&&coords[3]-coords[1]>1){snapshot();S.boxes.push({xyxy:coords,included:true,detector_score:null,origin:'human_review',page:S.page,class_name:'human_evidence'});S.selected=S.boxes.length-1;S.dirty=true}}if(drag.type==='resize'&&S.selected>=0){const b=S.boxes[S.selected];if(b.xyxy[0]>=b.xyxy[2]||b.xyxy[1]>=b.xyxy[3]){const restored=S.history.pop();S.boxes=restored.boxes;S.includedIds=restored.includedIds;S.dirty=true}}S.drag=null;refresh()}
canvas.addEventListener('pointerup',finishDrag);canvas.addEventListener('pointercancel',finishDrag);canvas.addEventListener('wheel',e=>{e.preventDefault();const r=canvas.getBoundingClientRect();zoom(Math.exp(-e.deltaY*.0015),e.clientX-r.left,e.clientY-r.top)},{passive:false});
for(const [id,tool] of [['panTool','pan'],['selectTool','select'],['addTool','add']])$(id).onclick=()=>selectTool(tool);$('deleteBox').onclick=deleteSelected;$('undo').onclick=()=>{if(S.history.length){const restored=S.history.pop();S.boxes=restored.boxes;S.includedIds=restored.includedIds;S.selected=-1;changed()}};$('fit').onclick=fit;$('zoomIn').onclick=()=>zoom(1.3);$('zoomOut').onclick=()=>zoom(1/1.3);new ResizeObserver(()=>draw()).observe($('viewer'));
function displayValue(value,unit){return value===null||value===undefined?'—':(typeof value==='object'?JSON.stringify(value):String(value))+(unit?' '+unit:'')}
function loadImage(src){return new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(Error('Preview could not be loaded'));image.src=src})}
async function changePage(page){if(!S.job)return;const job=S.job,ticket=S.pageTicket=(S.pageTicket||0)+1;S.page=Number(page);$('pageSelect').value=String(page);const image=await loadImage(`/api/jobs/${job.id}/page/${page}`);if(S.job!==job||ticket!==S.pageTicket)return;S.image=image;$('exportPng').href=`/api/jobs/${job.id}/export.png?page=${page}`;fit()}
$('pageSelect').onchange=()=>changePage($('pageSelect').value).then(()=>{S.selected=S.boxes.findIndex(b=>(b.page||1)===S.page);refresh()}).catch(e=>status(e.message,true));
async function chooseDocument(file,galleryId=null){const ticket=S.selectionVersion=(S.selectionVersion||0)+1;clearInspection('Validating drawing…');S.galleryId=galleryId;S.file=null;S.sample=null;S.validated=false;S.sourceCandidate=file;$('fileName').classList.remove('drawing-ready');$('fileName').textContent='Validating drawing…';updateAskState();if(!file)return;fillUploadSuggestions(file.name);try{const raw=await fileBase64(file),r=await api('/api/validate',{file_name:file.name,file_base64:raw});if(ticket!==S.selectionVersion)return;if(!r.ready)throw Error('Drawing was not accepted');S.file=file;S.validated=true;S.image=await loadImage(r.preview);$('empty').hidden=true;$('empty').style.display='none';$('fileName').textContent='✓ Drawing ready · '+file.name;$('fileName').classList.add('drawing-ready');fit();status('Drawing ready. Enter a question and Ask.');updateAskState()}catch(e){if(ticket===S.selectionVersion){S.validated=false;$('fileName').textContent='Drawing not accepted';status(e.message,true);updateAskState()}}}
function fileBase64(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file)})}
$('upload').onchange=()=>{setPresenterTab('live');return chooseDocument($('upload').files[0])};

$('executionMode').onchange=async()=>{if(S.config?.inspection){S.indexPage=0;await loadCurated();await refreshCases();return}if(S.config?.replay){try{await showReplay(S.replaySample)}catch(e){status(e.message,true)}return}try{const r=await api('/api/cloud-state',{enabled:$('executionMode').value==='hybrid'});$('cloudState').textContent=r.note;status(($('executionMode').value==='hybrid'?'Hybrid':'Local')+' selected for next Ask. Displayed answer is unchanged.')}catch(e){status(e.message,true)}};
$('examples').onchange=()=>{if($('examples').value)$('question').value=$('examples').value;showExpectedReference(null);S.expectedReference=null;updateAskState()};
$('manualAnswer').oninput=()=>changed();
function viewEvidence(){return S.activeEvidence||S.job?.prediction?.evidence||[]}
function evidenceTable(){const table=$('evidenceTable');table.replaceChildren();if(!S.job)return;for(const [n,e]of viewEvidence().entries()){const row=document.createElement('div');row.className='evidence-row';const link=document.createElement('button');link.textContent='#'+(n+1)+' '+(e.class||e.label||e.room_number||e.property||'Source');link.onclick=()=>{const i=S.boxes.findIndex(b=>b.evidence_id===e.id);if(i>=0)focusEvidence(i);else{S.evidenceOnly=e;S.ifcIndex=n;drawCrop()}};const source=document.createElement('span');source.textContent=evidenceProvenance(e);row.append(link,source);table.append(row)}if(!viewEvidence().length)table.textContent='No localized evidence recorded for this output.'}
async function syncPresentation(){if(!S.job)return;const job=S.job,mode=answerPresentation(job).kind==='hybrid'?'hybrid':'local',key=job.id+'|'+mode;if(S.presentationKey===key)return;S.presentationKey=key;const ticket=S.presentationTicket=(S.presentationTicket||0)+1;S.cropKey=null;S.cropRequest=(S.cropRequest||0)+1;S.evidenceOnly=null;S.selected=-1;S.activeEvidence=[];S.boxes=[];draw();drawCrop();evidenceTable();try{let data;if(mode==='local'||S.config?.replay)data={evidence:localPrediction(job)?.evidence||[],boxes:job.review.boxes};else data=await api(`/api/jobs/${job.id}/presentation?mode=hybrid`);if(S.job!==job||ticket!==S.presentationTicket)return;if(!Array.isArray(data.evidence)||!Array.isArray(data.boxes))throw Error('Saved evidence unavailable');S.activeEvidence=data.evidence;S.boxes=clone(data.boxes);if(!S.boxes.length){const overview=data.evidence.find(e=>e.kind==='source_overview');if(overview){const page=job.pages.find(p=>p.page===(overview.page||1));if(page)S.boxes=[{xyxy:[0,0,page.width,page.height],page:page.page,included:false,context_only:true,evidence_id:overview.id,class_name:'Page overview — no per-object locations'}]}}S.selected=S.boxes.length?0:-1;if(S.selected>=0&&(S.boxes[0].page||1)!==S.page)await changePage(S.boxes[0].page);evidenceTable();draw();drawCrop()}catch(e){if(ticket===S.presentationTicket){S.activeEvidence=[];S.boxes=[];draw();drawCrop();evidenceTable()}}}

async function displayJob(job){const renderToken=S.renderToken=(S.renderToken||0)+1;S.job=job;S.presentationKey=null;S.activeEvidence=null;S.evidenceOnly=null;S.ifcIndex=0;if(!S.config?.replay){try{const b=await api('/api/budget');$('budgetState').textContent=`Shared allowance: ${b.requests_reserved}/${b.requests_max} HTTP requests · US$${b.estimated_usd_reserved.toFixed(2)}/US$${b.estimated_usd_max.toFixed(2)} conservatively reserved.`}catch(e){$('budgetState').textContent='Shared budget status unavailable; provider admission remains enforced server-side.'}}S.boxes=clone(job.review.boxes);S.includedIds=clone(job.review.included_evidence_ids);S.selected=-1;S.page=1;S.history=[];S.dirty=false;$('pageSelect').replaceChildren();for(const p of job.pages){const option=document.createElement('option');option.value=p.page;option.textContent=p.page;$('pageSelect').append(option)}const loadedImage=await loadImage(`/api/jobs/${job.id}/image`);if(renderToken!==S.renderToken)return;S.image=loadedImage;$('empty').hidden=true;$('empty').style.display='none';$('drawingTitle').textContent=job.source_name;$('modelCount').textContent=displayValue(job.prediction.answer,job.prediction.unit);$('drawingCredit').textContent='';$('answerPanel').hidden=false;$('answerStatus').textContent=job.prediction.status.toUpperCase();$('answerStatus').classList.toggle('needs-review',job.prediction.status!=='success');$('routeLabel').textContent=`${job.prediction.route} · ${job.prediction.device||job.device} · ${job.prediction.timing.total_seconds.toFixed(3)} s`;$('answerText').textContent=job.prediction.status==='success'?displayValue(job.prediction.answer,job.prediction.unit):'No supported answer. Review the route limitations below.';$('answerWarnings').textContent=job.prediction.warnings.join(' ')+(job.prediction.local_baseline?.status==='success'&&job.prediction.local_baseline.answer!==job.prediction.answer?` Detector disagreement: CubiCasa ${job.prediction.local_baseline.answer}; selected result ${job.prediction.answer}. Review both recorded outputs; no averaging. `:'')+` Mode: ${job.prediction.execution_mode||'archived local'}. Cloud: ${job.prediction.cloud?.status||'off'}; reserved estimate $${job.prediction.cloud?.estimated_usd_reserved||0}.`;$('trace').textContent='';$('runDetails').textContent='';$('manualAnswer').value=job.review.answer===null?'':typeof job.review.answer==='object'?JSON.stringify(job.review.answer):String(job.review.answer);$('exportJson').href=`/api/jobs/${job.id}/export.json`;$('exportPng').href=`/api/jobs/${job.id}/export.png?page=1`;evidenceTable();fit();S.selected=S.boxes.length?0:-1;if(S.selected>=0&&(S.boxes[0].page||1)!==1)await changePage(S.boxes[0].page);refresh();compactJob();history.replaceState({},'',`?job=${job.id}`);if(S.config?.replay){const panel=$('recordedReference');panel.hidden=false;panel.textContent=`Reference: ${displayValue(job.replay.expected,job.replay.unit)} · ${job.replay.grade.passed===true?'Correct numeric':job.replay.grade.reason}`;document.querySelectorAll('.evidence-row input').forEach(e=>e.disabled=true);$('clearImage').hidden=true;$('clearQuestion').hidden=true;$('saveReview').hidden=true;$('manualAnswer').disabled=true;}}
async function pollResult(id,selection){let failures=0;while(true){let job;try{job=await api(`/api/jobs/${id}`);failures=0}catch(e){if([401,403,404].includes(e.httpStatus)||++failures>5)throw e;if(selection===(S.selectionVersion||0))status('Reconnecting… checking the same request');await new Promise(r=>setTimeout(r,Math.min(4000,500*2**(failures-1))));continue}if(selection!==(S.selectionVersion||0)){if(!['queued','running'].includes(job.status))return;await new Promise(r=>setTimeout(r,800));continue}if(!['queued','running'].includes(job.status)){if(job.status!=='success'){sessionStorage.removeItem('floorhawk-pending-job');throw Error((job.error||'Request failed')+' Ask again to retry safely.');}status('Preparing result');await displayJob(job);S.reuseJobId=job.id;S.validated=true;showExpectedReference(job.expected_reference);configureAnnotatedExport();sessionStorage.removeItem('floorhawk-pending-job');return}status(job.local_prediction?'Checking evidence':job.status==='queued'?'Reading drawing · queued':'Reading drawing');await new Promise(r=>setTimeout(r,800))}}
async function resumeJob(id){if(S.busy)return;S.busy=true;updateAskState();$('progress').hidden=false;const selection=S.selectionVersion||0;try{status('Reconnecting…');await pollResult(id,selection)}catch(e){status(e.message,true);$('retryStatus').hidden=false;$('retryStatus').onclick=()=>resumeJob(id)}finally{S.busy=false;$('progress').hidden=true;updateAskState()}}
async function analyze(sample){if(S.config?.replay){await showReplay(sample);return}if(!canAsk())return;const selection=S.selectionVersion||0;S.busy=true;updateAskState();$('progress').hidden=false;$('answerPanel').hidden=true;$('retryStatus').hidden=true;status('Reading drawing');S.requestKey=crypto.randomUUID();sessionStorage.removeItem('floorhawk-pending-job');sessionStorage.setItem('floorhawk-submission',S.requestKey);history.replaceState({},'',`?submission=${S.requestKey}`);try{const body={mode:'hybrid',question:$('question').value,credit:$('credit').value||'User-supplied drawing'};if(S.galleryId)body.gallery_id=S.galleryId;else if(!S.file&&S.reuseJobId)body.reuse_job_id=S.reuseJobId;else{body.file_name=S.file.name;body.file_base64=await fileBase64(S.file)}const {id}=await api('/api/jobs',body);sessionStorage.removeItem('floorhawk-submission');sessionStorage.setItem('floorhawk-pending-job',id);history.replaceState({},'',`?job=${id}`);if(selection===(S.selectionVersion||0)){$('fileName').textContent='✓ Drawing ready · '+(S.file?.name||'Curated example');$('fileName').classList.add('drawing-ready')}await pollResult(id,selection)}catch(e){if(selection===(S.selectionVersion||0)){status(e.message,true);if(sessionStorage.getItem('floorhawk-submission')){$('retryStatus').hidden=false;$('retryStatus').onclick=()=>recoverSubmission(sessionStorage.getItem('floorhawk-submission'))}else if(sessionStorage.getItem('floorhawk-pending-job')){$('retryStatus').hidden=false;$('retryStatus').onclick=()=>resumeJob(sessionStorage.getItem('floorhawk-pending-job'))}}}finally{S.busy=false;$('progress').hidden=true;updateAskState();exportState()}}

$('run').onclick=()=>analyze(S.sample||undefined);$('saveReview').onclick=async()=>{if(!S.job)return;try{let answer=$('manualAnswer').value;if(answer.trim()!==''&&Number.isFinite(Number(answer)))answer=Number(answer);const record=await api(`/api/jobs/${S.job.id}/review`,{base_revision:S.job.review.revision,boxes:S.boxes,included_evidence_ids:S.includedIds,answer,unit:S.job.review.unit});S.job.review=record;S.boxes=clone(record.boxes);S.dirty=false;status('Human review saved; original model/tool answer preserved.');refresh()}catch(e){status(e.message,true)}};
$('workspaceTab').onclick=()=>{$('workspace').hidden=false;$('evaluation').hidden=true;$('workspaceTab').classList.add('active');$('evaluationTab').classList.remove('active');draw()};
let evaluation;
$('evaluationTab').onclick=async()=>{$('workspace').hidden=true;$('evaluation').hidden=false;$('workspaceTab').classList.remove('active');$('evaluationTab').classList.add('active');try{evaluation=await api('/api/qa-evaluation');$('reportSelect').replaceChildren();for(let i=0;i<evaluation.reports.length;i++){const option=document.createElement('option');option.value=i;option.textContent=evaluation.reports[i].label;$('reportSelect').append(option)}renderReport()}catch(e){$('evalNote').textContent=e.message}};
function renderReport(){const report=evaluation?.reports[Number($('reportSelect').value)];if(!report){$('evalNote').textContent=evaluation?.note||'No offline QA reports yet.';return}const m=report.summary;$('metrics').replaceChildren();for(const [label,value] of [['Questions',m.total],[`Numeric pass (${m.numeric_passed}/${m.numeric_total})`,`${(100*m.numeric_accuracy).toFixed(1)}%`],['Coverage',`${(100*m.coverage).toFixed(1)}%`],['Count MAE',m.count_mae?.toFixed(2)??'—'],['Abstained',m.statuses.abstained||0],['Failed',m.statuses.failed||0]]){const div=document.createElement('div');div.className='metric';const strong=document.createElement('strong');strong.textContent=value;const text=document.createElement('span');text.textContent=label;div.append(strong,text);$('metrics').append(div)}$('evalNote').textContent=report.note;$('gallery').replaceChildren();for(const sample of report.samples){const card=document.createElement('article');card.className='card'+(sample.passed?'':' failure');const title=document.createElement('h3');title.textContent=`${sample.sample_id} · ${sample.status}`;const q=document.createElement('p');q.textContent=sample.question;const answer=document.createElement('p');answer.textContent=`Model: ${displayValue(sample.answer,sample.unit)} · Reference: ${displayValue(sample.expected,sample.expected_unit)} · ${sample.reason}`;const route=document.createElement('small');route.textContent=sample.route;card.append(title,q,answer,route);if(sample.overlay){const link=document.createElement('a');link.href='/qa-gallery/'+sample.overlay;link.target='_blank';link.rel='noopener';const image=document.createElement('img');image.src=link.href;image.alt='Numbered model evidence overlay; reference counts are evaluation-only';image.loading='lazy';image.className='evaluation-overlay';link.append(image);card.append(link)}$('gallery').append(card)}}
$('reportSelect').onchange=renderReport;

async function showReplay(sample){
 if(!sample)return;S.replaySample=sample;$('sampleSelect').value=sample;const entry=S.config.samples.find(s=>s.id===sample);const mode=$('executionMode').value;const saved=entry?.modes[mode];if(entry)$('question').value=entry.credit;
 if(!saved){S.job=null;S.image=null;S.evidenceOnly=null;S.boxes=[];S.includedIds=[];S.selected=-1;draw();drawCrop();$('reviewCount').textContent='—';$('drawingTitle').textContent='Not recorded for selected mode';$('evidenceTable').replaceChildren();exportState();status('not recorded for this mode; no generation will run.');$('answerText').textContent='not recorded';$('answerStatus').textContent='NOT RECORDED';$('routeLabel').textContent='';$('answerWarnings').textContent='No saved result for the selected mode.';refresh();$('modelCount').textContent='—';$('recordedReference').textContent='No saved answer/reference for this mode.';return}
 const job=await api(`/api/jobs/${saved.id}`);await displayJob(job);$('question').value=job.question;status('Recorded evaluation result loaded. No model inference or provider request.');
}
function configureReplay(){document.body.classList.add('replay');$('runMode').textContent='Recorded replay — no live inference';$('executionMode').options[0].textContent='Local';$('executionMode').options[1].textContent='Hybrid';for(const id of ['clearImage','clearQuestion','run','upload','selectTool','addTool','deleteBox','undo','saveReview','resetReview'])$(id).hidden=true;$('question').readOnly=true;$('question').setAttribute('aria-label','Recorded question');document.querySelector('.upload').hidden=true;$('deviceBadge').textContent='Recorded devices · no model loaded';$('cloudState').textContent='Saved Local/Hybrid results only; no model/API calls. --include-failures includes wrong and abstained examples.'}

(async()=>{try{S.config=await api('/api/config');if(S.config.presenter)document.body.classList.add('presenter-mode');if(sessionStorage.getItem('floorhawk-tab')==='samples')showGallery().catch(e=>status(e.message,true));$('diagnosticsButton').hidden=!S.config.diagnostics;if(S.config.replay){configureReplay();$('geminiControl').hidden=true}else{document.querySelector('.mode-control').hidden=true;$('executionMode').value='local';$('geminiToggle').checked=false;}if(S.config.inspection){await setupInspection();return;}else if(S.config.replay&&S.config.cloud?.default_mode==='hybrid')$('executionMode').value='hybrid';if(!S.config.replay)$('deviceBadge').textContent='CPU tools · host GPU '+(S.config.host_vision?'ready':'vision restart needed');for(const sample of S.config.samples){const option=document.createElement('option');option.value=sample.id;option.textContent=sample.id+(S.config.replay?' · '+sample.credit.slice(0,85):'');$('sampleSelect').append(option);const button=document.createElement('button');button.textContent=`Open ${sample.id} ↗`;button.onclick=()=>analyze(sample.id);$('samples').append(button)}if(S.config.replay){const first=S.config.samples.find(s=>s.modes.local)||S.config.samples[0];if(first&&!first.modes.local)$('executionMode').value='hybrid';await showReplay(first?.id);return}const submission=new URLSearchParams(location.search).get('submission')||sessionStorage.getItem('floorhawk-submission');if(submission){recoverSubmission(submission);return}const saved=new URLSearchParams(location.search).get('job')||sessionStorage.getItem('floorhawk-pending-job');if(saved){const job=await api(`/api/jobs/${saved}`);if(job.status==='success'){await restoreCompletedJob(job);status('Saved answer and review reopened from this machine.')}}}catch(e){status(e.message,true)}})();

