async function focusEvidence(index){if(!Number.isInteger(index)||index<0||index>=S.boxes.length)return;S.selected=index;S.evidenceOnly=null;S.overlay=true;$('overlayToggle').setAttribute('aria-pressed','true');const b=S.boxes[index];if((b.page||1)!==S.page)await changePage(b.page||1);const [x1,y1,x2,y2]=b.xyxy,r=canvas.getBoundingClientRect();S.scale=Math.min(5,Math.max(.05,Math.min(r.width/(Math.max(80,x2-x1)*2.5),r.height/(Math.max(80,y2-y1)*2.5))));S.ox=r.width/2-(x1+x2)/2*S.scale;S.oy=r.height/2-(y1+y2)/2*S.scale;refresh()}
function drawCrop(){const c=$('cropCanvas'),r=c.getBoundingClientRect(),d=devicePixelRatio||1;c.width=Math.max(1,Math.round(r.width*d));c.height=Math.max(1,Math.round(r.height*d));const cc=c.getContext('2d');cc.setTransform(d,0,0,d,0,0);cc.clearRect(0,0,r.width,r.height);$('evidencePosition').textContent=S.selected>=0?`${S.selected+1}/${S.boxes.length}`:'—';if(S.job?.input_kind==='ifc'){const items=viewEvidence();const e=S.evidenceOnly||items[S.ifcIndex||0];$('evidencePosition').textContent=items.length?`${items.indexOf(e)+1}/${items.length}`:'—';$('cropNotice').hidden=false;$('cropNotice').textContent=e?[e.guid,e.property,e.value_si??e.value,e.unit,e.text].filter(x=>x!==undefined&&x!==null).join(' · '):'No GUID/property evidence recorded.';$('cropCaption').textContent=e?evidenceProvenance(e)+' · IFC property evidence; no image localization invented.':'IFC property evidence; no image localization invented.';if(S.contextIFC)$('cropNotice').textContent='Context only — no recorded evidence link: '+S.contextIFC.guid+' · '+S.contextIFC.type;else window.IFCView?.selectRecorded(e?.guid);$('highResCrop').hidden=true;$('fullEvidence').hidden=true;return}const b=S.boxes[S.selected];if(!S.image||!b){$('cropNotice').hidden=false;$('cropNotice').textContent=S.job?'No localized evidence for this answer.':'Select evidence to inspect its source.';$('cropCaption').textContent='';$('highResCrop').hidden=true;$('fullEvidence').hidden=true;return}if((b.page||1)!==S.page)return;const [x1,y1,x2,y2]=b.xyxy,pad=Math.max(18,(x2-x1)*.25,(y2-y1)*.3),sx=Math.max(0,x1-pad),sy=Math.max(0,y1-pad),sw=Math.min(S.image.width,x2+pad)-sx,sh=Math.min(S.image.height,y2+pad)-sy,scale=Math.min(r.width/sw,r.height/sh),ox=(r.width-sw*scale)/2,oy=(r.height-sh*scale)/2;cc.drawImage(S.image,sx,sy,sw,sh,ox,oy,sw*scale,sh*scale);cc.strokeStyle='#f000b8';cc.lineWidth=1.5;cc.fillStyle='#167bea18';cc.fillRect(ox+(x1-sx)*scale,oy+(y1-sy)*scale,(x2-x1)*scale,(y2-y1)*scale);cc.strokeRect(ox+(x1-sx)*scale,oy+(y1-sy)*scale,(x2-x1)*scale,(y2-y1)*scale);$('cropNotice').hidden=true;const e=viewEvidence().find(e=>e.id===b.evidence_id);$('cropCaption').textContent=b.context_only?'Gemini · page overview only; no per-object locations returned':[`#${S.selected+1}`,String(e?.label||e?.text||b.class_name||'Evidence').slice(0,80),[evidenceProvenance(e),answerPresentation(S.job).kind==='hybrid'?(S.job.prediction.paired?.hybrid?.provider_invoked===false?'Specialist':'Gemini'):null].filter(Boolean).join(' + ')].join(' · ');requestSourceCrop(b)}
function compactJob(){const p=S.job.prediction;const executions=p.live_execution||[];const ex=executions.findLast(e=>!e.cache_hit)||executions.at(-1);$('deviceBadge').textContent=S.config.replay?`Recorded device: ${p.device||S.job.device||'not recorded'}`:ex?`${ex.model} · ${ex.device}${ex.cache_hit?' · cached':''}${ex.fallback_reason?' · fallback':''}`:`${p.device||'CPU'} · ${p.timing?.cache_hit?'cached':'recorded execution'}`;$('deviceBadge').title=ex?.fallback_reason||'Actual recorded execution; caches do not run a model';$('routeLabel').textContent=`${p.route} · ${p.timing?.total_seconds?.toFixed(2)||'—'} s`;$('answerWarnings').textContent=(p.status==='success'?(p.warnings||[]).slice(0,2):(p.warnings||[]).slice(-2)).join(' ');if(ex?.fallback_reason)$('answerWarnings').textContent+=' CPU fallback: '+ex.fallback_reason;$('manualAnswerLabel').hidden=!!S.job.review.instance_count||!!S.config.replay;drawCrop();showModelContext();renderPaired(S.job);}
