function stepEvidence(delta){if(S.job?.input_kind==='ifc'){const n=viewEvidence().length;if(!n)return;S.contextIFC=null;S.ifcIndex=((S.ifcIndex||0)+delta+n)%n;S.evidenceOnly=null;drawCrop();return}if(S.boxes.length)focusEvidence((S.selected+delta+S.boxes.length)%S.boxes.length)}$('evidencePrev').onclick=()=>stepEvidence(-1);$('evidenceNext').onclick=()=>stepEvidence(1);
