$('diagnosticsButton').onclick=()=>{const root=$('diagnosticSteps');root.replaceChildren();const job=S.job,p=job?.prediction;const add=(title,line)=>{const el=document.createElement('section');el.className='trace-step';const h=document.createElement('strong');h.textContent=title;const text=document.createElement('p');text.textContent=String(line||'Not recorded');el.append(h,text);root.append(el)};add('Input',job?`${job.input_kind} · ${job.source_name}`:'No input selected');if(p){add('Question interpretation',p.task?`${p.task.operation} · ${p.task.target} · ${p.task.scope||'drawing'}`:'Not recorded');for(const step of (p.route_decisions||[]))add(step.stage||'Tool',`${step.route||''} · ${step.status||'recorded'}`);for(const [name,t]of Object.entries(p.stage_timings||{})){const sec=t?.inference_seconds??t?.total_seconds??t?.timing_seconds;add(name,(t?.cache_hit?'Cached · ':'')+(sec!==undefined?Number(sec).toFixed(3)+' s':'Timing not recorded'))}for(const ex of (p.live_execution||[]))add(ex.model,`${ex.device} · ${ex.cache_hit?'cached result':'executed'}${ex.peak_gpu_memory_bytes?' · peak '+(ex.peak_gpu_memory_bytes/1048576).toFixed(0)+' MiB':''}${ex.fallback_reason?' · '+ex.fallback_reason:''}`);add('Evidence',`${p.evidence.length} recorded regions/properties; quantity may differ from region count`);add('Answer',`${p.status} · ${displayValue(p.answer,p.unit)}`);if(p.warnings?.length)add('Uncertainty',(p.status==='success'?p.warnings.slice(0,2):p.warnings.slice(-2)).join(' '));if(p.paired?.hybrid){const h=p.paired.hybrid;add('Hybrid review',`${h.generation?.at(-1)?.model||'Gemini'} · ${h.status} · ${h.provider_attempts||0} HTTP attempts · ${h.timing?.additional_gemini_seconds?.toFixed(2)||'—'} s`);if(p.paired.decision)add('Selected output',`${p.paired.decision.selected} · ${p.paired.decision.reason||''}`)}}$('diagnostics').showModal()};$('closeDiagnostics').onclick=()=>$('diagnostics').close();
