function clearInspection(message='Loading saved result…'){modelTicket++;$('question').value='';$('drawingTitle').textContent='No drawing selected';$('drawingCredit').textContent='';S.renderToken=(S.renderToken||0)+1;S.job=null;S.reuseJobId=null;S.activeEvidence=null;S.presentationKey=null;S.presentationTicket=(S.presentationTicket||0)+1;S.image=null;S.boxes=[];S.dirty=false;S.showLocal=false;$('showLocalAnswer').checked=false;$('pairedAnswers').hidden=true;$('answerPanel').hidden=true;S.selected=-1;S.includedIds=[];S.cropKey=null;S.cropRequest=(S.cropRequest||0)+1;S.contextIFC=null;window.IFCView?.clear();$('ifcViewer').hidden=true;$('modelCount').textContent='—';$('reviewCount').textContent='—';$('answerStatus').textContent='';$('routeLabel').textContent='';$('answerWarnings').textContent='';$('groundTruthPanel').hidden=true;$('translationPanel').hidden=true;$('translationPanel').open=false;$('recordedReference').hidden=true;$('evidenceTable').replaceChildren();$('boxList').replaceChildren();$('highResCrop').hidden=true;$('fullEvidence').hidden=true;draw();drawCrop();exportState();configureAnnotatedExport();showExpectedReference(null);S.expectedReference=null;status(message)}
async function setupInspection(){document.body.classList.add('inspection');$('evaluationTab').textContent='Analytics ↗';$('evaluationTab').onclick=()=>window.open('/analytics/report','_blank','noopener');$('inspectionFilters').hidden=false;for(const run of S.config.runs){const option=document.createElement('option');option.value=run.id;option.textContent=`${run.label||run.id} · ${run.mode} · ${run.recorded}/${run.manifest_n}`;$('runSelect').append(option)}$('runSelect').value=S.config.default_run;$('outcomeFilter').value=S.config.default_outcome||'all';S.indexPage=0;await loadFacets();await refreshCases();}
async function loadFacets(){const run=$('runSelect').value;const f=await api('/api/inspection/facets?run='+encodeURIComponent(run));for(const [id,key,label]of[['formatFilter','formats','All formats'],['datasetFilter','datasets','All datasets'],['targetFilter','targets','All targets']]){const select=$(id);select.replaceChildren(new Option(label,''));for(const value of f[key])select.append(new Option(value,value))}await loadCurated();}
async function loadCurated(){const run=$('runSelect').value,mode=$('executionMode').value;const curated=await api('/api/inspection/curated?run='+encodeURIComponent(run)+'&mode='+mode);if(run!==$('runSelect').value||mode!==$('executionMode').value)return;$('curatedSelect').replaceChildren(new Option('Starting examples…',''));for(const e of curated.cases)$('curatedSelect').append(new Option(e.label,e.id));}
async function refreshCases(){S.caseLoad=(S.caseLoad||0)+1;const ticket=S.caseTicket=(S.caseTicket||0)+1;clearInspection('Filtering saved results…');const params=new URLSearchParams({run:$('runSelect').value,mode:$('executionMode').value,outcome:$('outcomeFilter').value,format:$('formatFilter').value,dataset:$('datasetFilter').value,target:$('targetFilter').value,page:String(S.indexPage||0)});try{const result=await api('/api/inspection/cases?'+params);if(ticket!==S.caseTicket)return;S.indexPage=result.page;$('sampleSelect').replaceChildren();for(const e of result.cases)$('sampleSelect').append(new Option(`${e.sample_id} · ${e.outcome} · ${e.question}`,e.id));$('matchingCount').textContent=`${result.total} matches · ${result.page+1}/${result.pages}`;$('casesPrev').disabled=result.page===0;$('casesNext').disabled=result.page+1>=result.pages;if(!result.cases.length){$('sampleSelect').append(new Option('No matching saved results',''));clearInspection('No questions match these filters. Change outcome, datatype, dataset, target or run.');return}await showIndexed(result.cases[0].id)}catch(e){if(ticket===S.caseTicket)clearInspection('Saved-result filter failed: '+e.message)}}
async function showIndexed(id){if(!id)return;const ticket=S.caseLoad=(S.caseLoad||0)+1;clearInspection();try{const job=await api('/api/jobs/'+id);if(ticket!==S.caseLoad)return;await displayJob(job);if(ticket!==S.caseLoad)return;S.replaySample=id;$('question').value=job.question;renderReference(job);status(`${job.replay.outcome} · ${job.replay.run_id} · ${job.replay.mode} · saved result, no inference`)}catch(e){if(ticket===S.caseLoad)clearInspection('Saved answer unavailable: '+e.message)}}
for(const id of ['outcomeFilter','formatFilter','datasetFilter','targetFilter'])$(id).onchange=()=>{S.indexPage=0;refreshCases()};$('runSelect').onchange=async()=>{S.indexPage=0;const r=S.config.runs.find(x=>x.id===$('runSelect').value);if(r)$('executionMode').value=r.mode;await loadFacets();refreshCases()};$('casesPrev').onclick=()=>{S.indexPage=Math.max(0,S.indexPage-1);refreshCases()};$('casesNext').onclick=()=>{S.indexPage++;refreshCases()};$('curatedSelect').onchange=()=>{const selected=$('curatedSelect').selectedOptions[0];if(!selected.value)return;if(![...$('sampleSelect').options].some(o=>o.value===selected.value))$('sampleSelect').append(new Option(selected.textContent,selected.value));$('sampleSelect').value=selected.value;showIndexed(selected.value)};
function renderReference(job){if(!S.config?.replay||!job?.replay){$('groundTruthPanel').hidden=true;return}const r=job.replay,p=job.prediction,t=job.english_translation;$('translationPanel').hidden=!t;$('translationPanel').open=false;$('englishQuestion').textContent=t?.english||'';$('groundTruthPanel').hidden=false;$('groundTruthValue').textContent=displayValue(r.expected,r.unit);let line;if(r.missing_recording||p.status==='not_recorded')line=`No saved ${r.mode||$('executionMode').value} prediction exists for this question in selected run.`;else if(r.grade.passed===true)line=r.question_type==='count'||p.unit==='count'?`Matches the reference count: ${r.expected}.`:'Within the saved evaluator tolerance.';else if(p.status==='abstained')line='Abstained: '+(p.warnings?.at(-1)||'no reason was recorded.');else if(p.status==='unsupported')line='Unsupported: '+(p.warnings?.at(-1)||'saved task not supported.');else if(p.status==='failed')line='Execution error: '+(p.error||p.warnings?.at(-1)||'saved execution failed.');else if(r.grade.passed===null)line='Saved answer is ungraded; no text correctness rubric is recorded.';else if(r.question_type==='count'&&typeof r.signed_error==='number')line=`Predicted ${p.answer}; reference ${r.expected}. Count is ${r.signed_error<0?'lower':'higher'} by ${Math.abs(r.signed_error)}. This does not identify missed or extra objects.`;else line=`Saved prediction differs from the reference (${r.grade.reason}).`;$('caseExplanation').textContent=line;$('recordedReference').hidden=true;}
function requestSourceCrop(b){if(!S.job||S.job.input_kind==='ifc')return;const key=[S.job.id,S.page,...b.xyxy.map(x=>x.toFixed(3))].join('|');if(S.cropKey===key)return;S.cropKey=key;const ticket=S.cropRequest=(S.cropRequest||0)+1;const url=`/api/jobs/${S.job.id}/crop.png?`+new URLSearchParams({page:String(S.page),bbox:b.xyxy.join(',')});const image=$('highResCrop');image.hidden=true;$('cropCanvas').hidden=true;$('cropNotice').hidden=false;$('cropNotice').textContent='Loading original-resolution source region…';$('fullEvidence').hidden=true;const pending=new Image();pending.onload=()=>{if(ticket!==S.cropRequest)return;image.src=url;image.hidden=false;$('cropNotice').hidden=true;$('fullEvidence').href=url;$('fullEvidence').hidden=false;};pending.onerror=()=>{if(ticket!==S.cropRequest)return;$('cropNotice').textContent='Source-resolution evidence unavailable. Recorded answer and coordinates are retained.';};pending.src=url;}
let modelTicket=0;
async function showModelContext(){const ticket=++modelTicket;if(S.job?.input_kind!=='ifc'){window.IFCView?.clear();$('ifcViewer').hidden=true;return}$('ifcViewer').hidden=false;$('ifcStatus').textContent='Loading cached IFC geometry…';const job=S.job;try{let meta=await api(`/api/jobs/${job.id}/model`+(S.config.replay?'':'?start=1'));for(let i=0;!S.config.replay&&['queued','converting','busy'].includes(meta.status)&&i<6;i++){if(ticket!==modelTicket)return;$('ifcCancel').hidden=false;await new Promise(r=>setTimeout(r,350));meta=await api(`/api/jobs/${job.id}/model?start=1`)}if(ticket!==modelTicket)return;$('ifcCancel').hidden=true;if(!['ready','empty'].includes(meta.status)){$('ifcStatus').textContent=meta.note||'No cached supported geometry; GUID/property evidence remains.';$('ifcViewer').hidden=true;return}window.IFCView=await import('/ifc-viewer.js');if(ticket!==modelTicket)return;const guids=job.prediction.evidence.map(e=>e.guid).filter(Boolean);const result=await window.IFCView.load(meta.glb_url,meta,guids,info=>{if(S.job?.id!==job.id)return;const e=viewEvidence().find(e=>e.guid===info.guid);if(e){S.contextIFC=null;S.evidenceOnly=e;S.ifcIndex=viewEvidence().indexOf(e)}else S.contextIFC=info;drawCrop()});if(ticket!==modelTicket)return;$('ifcStatus').textContent=`${result.meshes} source meshes · ${result.linked} recorded GUIDs linked${meta.partial?' · partial conversion':''}`;window.IFCView.selectRecorded(S.evidenceOnly?.guid||job.prediction.evidence[0]?.guid)}catch(e){if(ticket===modelTicket)$('ifcViewer').hidden=true;$('ifcStatus').textContent='3D context unavailable; recorded GUID/property evidence remains. '+e.message}}
$('ifcFit').onclick=()=>window.IFCView?.fit();$('ifcFade').onchange=()=>window.IFCView?.contextFade($('ifcFade').checked);$('ifcCancel').onclick=async()=>{if(S.job&&!S.config.replay){await api(`/api/jobs/${S.job.id}/model-cancel`,{});$('ifcStatus').textContent='Geometry conversion cancelled; saved answer retained.'}};

function localPrediction(job){return job?.prediction?.paired?.local||job?.prediction}
function hybridCitesEvidence(id){return !!id&&!!S.job?.prediction?.paired?.hybrid?.evidence_ids?.includes(id)}
function evidenceProvenance(e){if(!e)return 'Source not recorded';const source=e.origin_model||e.source_model||e.detector_model||e.model?.name||(typeof e.model==='string'?e.model:null)||e.method||(e.kind?.startsWith('native_')?'Native PDF vectors':e.id?.startsWith('rtdetr')?'RT-DETR':e.guid?'IFC':'Recorded source');return String(source)+(e.verified_local_evidence===false?' · Gemini proposed, unverified':'')}

function answerPresentation(job){const pair=job?.prediction?.paired,local=pair?.local||job.prediction,hybrid=pair?.hybrid,decision=pair?.decision;if(S.config?.replay&&!pair)return{answer:job.prediction,label:'Recorded prediction',kind:'recorded'};if(S.showLocal&&pair)return{answer:local,label:'Local result',kind:'local'};if(!pair)return{answer:local,label:job.mode==='hybrid'?'Local ready · Hybrid pending':'Local result',kind:'local'};if(decision?.selected==='local')return{answer:local,label:'Local retained after Hybrid review',kind:'fallback',reason:decision.reason};if(decision?.selected==='abstained')return{answer:{status:'abstained',answer:null,unit:null,explanation:decision.reason},label:'Hybrid review abstained',kind:'hybrid'};if(['provider_error','validation_error','blocked','failed','disabled'].includes(hybrid?.status))return{answer:local,label:'Local fallback · Hybrid unavailable',kind:'fallback',reason:hybrid.explanation||hybrid.status};return{answer:hybrid||{status:'pending',answer:null,unit:null},label:'Hybrid review',kind:'hybrid'}}
function renderPaired(job){if(!job)return;const pair=job.prediction?.paired,local=localPrediction(job),hybrid=pair?.hybrid;const hybridRequest=!S.config?.replay&&(job.mode==='hybrid'||!!pair);if(S.answerJobId!==job.id){S.answerJobId=job.id;S.showLocal=false;$('showLocalAnswer').checked=false}$('pairedAnswers').hidden=!hybridRequest;$('showLocalControl').hidden=!pair;$('pairedLocalRow').hidden=!S.showLocal;$('pairedHybridRow').hidden=!S.showLocal;$('pairedLocal').textContent=displayValue(local?.answer,local?.unit)+' · '+(local?.status||'pending');$('pairedHybrid').textContent=hybrid?(hybrid.status==='success'?displayValue(hybrid.answer,hybrid.unit):hybrid.status):'Pending…';$('pairedNote').textContent=hybrid?(hybrid.explanation||'')+' · '+(hybrid.generation?.at(-1)?.model||'Gemini')+' · '+(hybrid.provider_attempts||0)+' HTTP attempts · '+(hybrid.timing?.additional_gemini_seconds?.toFixed(2)||'—')+' s; review may be wrong.':hybridRequest?'Local is saved. Waiting for the separate Hybrid review.':'';if(pair?.decision?.reason)$('pairedNote').textContent+=' Decision: '+pair.decision.reason;$('reviewLabel').textContent=S.config?.replay?'Reviewed answer':'Reviewed Local answer';if(!S.config?.replay){const view=answerPresentation(job),p=view.answer||{};$('answerSource').textContent=view.label;$('modelCount').textContent=displayValue(p.answer,p.unit);$('answerStatus').textContent=String(p.status||'pending').toUpperCase();$('answerStatus').classList.toggle('needs-review',p.status!=='success');$('routeLabel').textContent=view.kind==='hybrid'?`${hybrid?.generation?.at(-1)?.model||'Gemini review'} · ${hybrid?.timing?.additional_gemini_seconds?.toFixed(2)||'—'} s additional`:`${local?.route||'Local'} · ${local?.timing?.total_seconds?.toFixed(2)||'—'} s`;$('answerWarnings').textContent=view.kind==='hybrid'?(p.explanation||'Inspect the cited Local evidence; no completeness guarantee.'):(view.reason?view.reason+' ':'')+(local?.warnings||[]).slice(0,2).join(' ');const fallback=(local?.live_execution||job.prediction?.live_execution||[]).findLast(e=>e.fallback_reason);if(fallback&&view.kind!=='hybrid')$('answerWarnings').textContent+=' CPU fallback: '+fallback.fallback_reason}document.querySelector('.review-bottom').inert=!!S.busy&&!pair;syncPresentation();}
$('showLocalAnswer').onchange=()=>{S.showLocal=$('showLocalAnswer').checked;renderPaired(S.job);evidenceTable();draw();drawCrop()};
$('clearImage').onclick=()=>{S.selectionVersion=(S.selectionVersion||0)+1;const question=$('question').value;S.file=null;S.sample=null;$('upload').value='';$('sampleSelect').value='';clearInspection('Drawing cleared. Choose a drawing before Ask.');$('question').value=question;$('fileName').textContent='No drawing selected';updateAskState()};
$('clearQuestion').onclick=()=>{S.selectionVersion=(S.selectionVersion||0)+1;clearInspection('Question and previous answer cleared. Drawing selection retained; enter a new question.');$('question').value='';updateAskState()};

$('geminiToggle').onchange=()=>{$('executionMode').value=$('geminiToggle').checked?'hybrid':'local';$('executionMode').dispatchEvent(new Event('change'))};

// One result policy: a valid Hybrid proposal; explicit Local fallback on provider failure.
const originalRenderPaired=renderPaired;
renderPaired=function(job){originalRenderPaired(job);if(S.config?.replay)return;const view=answerPresentation(job);$('answerSource').textContent='Result';if(view.kind==='fallback'){$('answerStatus').textContent='Local fallback — Gemini unavailable';$('answerWarnings').textContent=(view.reason||'Gemini unavailable. Local output retained; inspect its evidence.')}else if(!job.prediction?.paired){$('answerPanel').hidden=true}configureAnnotatedExport()};
function configureAnnotatedExport(){const button=$('annotatedExport');button.disabled=!S.job||S.job.status!=='success'||S.job.input_kind==='ifc';button.title=S.job?.input_kind==='ifc'?'No rendered IFC view available':!S.job?'Run a question first':'Whole source/current page with actual evidence overlays';button.onclick=()=>{if(!button.disabled)location.href=`/api/jobs/${S.job.id}/annotated.png?page=${S.page}`}}
function showExpectedReference(ref){const panel=$('expectedReference');const exact=ref&&ref.question===$('question').value;panel.hidden=!exact;if(exact){S.expectedReference=ref;$('expectedReferenceValue').textContent=displayValue(ref.value,ref.unit);$('expectedReferenceNote').textContent=ref.verification||'Curated reference; separate from computed result'}}
$('question').addEventListener('input',()=>showExpectedReference(S.expectedReference));
let curated=[];
async function showGallery(){if(!curated.length)curated=await api('/api/gallery');$('liveGallery').hidden=false;document.querySelector('.upload').hidden=true;fillGalleryDrawings()}
function fillGalleryDrawings(){$('galleryDrawing').replaceChildren(new Option('Drawing…',''));for(const row of curated.filter(r=>r.format===$('galleryFormat').value))$('galleryDrawing').add(new Option(row.name,row.id));$('galleryQuestion').replaceChildren(new Option('Suggested question…',''))}
$('preloadedTab').onclick=()=>{setPresenterTab('samples');showGallery().catch(e=>status(e.message,true))};$('workspaceTab').onclick=()=>{setPresenterTab('live');$('liveGallery').hidden=true;document.querySelector('.upload').hidden=false;S.galleryId=null;showExpectedReference(null);S.expectedReference=null};$('galleryFormat').onchange=fillGalleryDrawings;
$('galleryDrawing').onchange=async()=>{const row=curated.find(r=>r.id===$('galleryDrawing').value);if(!row)return;const ticket=S.galleryFetchTicket=(S.galleryFetchTicket||0)+1;S.selectionVersion=(S.selectionVersion||0)+1;clearInspection('Loading curated drawing…');S.file=null;S.galleryId=null;S.validated=false;updateAskState();$('question').value='';showExpectedReference(null);$('galleryQuestion').replaceChildren(new Option('Suggested question…',''));for(const q of row.suggestions)$('galleryQuestion').add(new Option(q.question,q.id));const response=await fetch('/api/gallery/'+row.id+'/source');if(!response.ok)throw Error('Curated source unavailable');if(ticket!==S.galleryFetchTicket||$('galleryDrawing').value!==row.id)return;await chooseDocument(new File([await response.blob()],row.filename),row.id)};
$('galleryQuestion').onchange=()=>{const row=curated.find(r=>r.id===$('galleryDrawing').value),q=row?.suggestions.find(q=>q.id===$('galleryQuestion').value);if(!q)return;$('question').value=q.question;S.expectedReference='reference'in q?{question:q.question,value:q.reference,unit:q.unit,verification:q.verification}:null;showExpectedReference(S.expectedReference);updateAskState()};

const previousModelContext=showModelContext;showModelContext=async function(){if(S.job?.input_kind!=='ifc')return previousModelContext();const attempt=S.ifcAttempt=(S.ifcAttempt||0)+1;let ready=false;const timer=setTimeout(()=>{if(!ready&&S.ifcAttempt===attempt){$('ifcStatus').textContent='Answer ready · loading IFC geometry in background…'}},3000);try{await previousModelContext();ready=true}finally{clearTimeout(timer)}};

async function recoverSubmission(key){S.busy=true;updateAskState();status('Reconnecting… finding the accepted request');try{for(let i=0;i<20;i++){const r=await api('/api/submissions/'+key);if(r.id){sessionStorage.removeItem('floorhawk-submission');sessionStorage.setItem('floorhawk-pending-job',r.id);history.replaceState({},'',`?job=${r.id}`);S.busy=false;return resumeJob(r.id)}await new Promise(r=>setTimeout(r,500))}sessionStorage.removeItem('floorhawk-submission');status('Submission was not accepted. Upload the drawing and Ask again.',true)}catch(e){status('Reconnecting failed. Reload to find the same request; inference was not resubmitted.',true)}finally{S.busy=false;updateAskState()}}

function setPresenterTab(mode){sessionStorage.setItem('floorhawk-tab',mode);$('workspaceTab').classList.toggle('active',mode==='live');$('preloadedTab').classList.toggle('active',mode==='samples');$('workspaceTab').setAttribute('aria-selected',String(mode==='live'));$('preloadedTab').setAttribute('aria-selected',String(mode==='samples'))}
setPresenterTab(sessionStorage.getItem('floorhawk-tab')||'live');
const presenterRender=renderPaired;renderPaired=function(job){presenterRender(job);const h=job?.prediction?.paired?.hybrid;if(h?.provider_invoked===false&&h.supporting_tool)$('routeLabel').textContent=h.supporting_tool+' · specialist evidence';};

function fillUploadSuggestions(name){const ext=name.split('.').pop().toLowerCase();const questions=ext==='ifc'?['How many windows are in this IFC model?','How many storeys are in this IFC model?','What IFC schema does this model use?']:ext==='pdf'?['What is the net floor area of room 1.01 in m²?',"How many rooms labelled 'Küche' are there on this floor?",'What notes are printed on this page?']:['How many windows are shown on this floor plan?','How many doors are shown on this floor plan?','How many toilet bowls are shown on this floor plan?','Which rooms are labelled on this floor plan?'];$('examples').replaceChildren(new Option('Suggested questions (optional)…',''));for(const q of questions)$('examples').add(new Option(q,q))}

async function restoreCompletedJob(job){
 $('question').value=job.question;
 await displayJob(job);
 S.reuseJobId=job.id;S.validated=true;
 const isCurated=!!job.expected_reference;
 setPresenterTab(isCurated?'samples':'live');
 $('liveGallery').hidden=!isCurated;document.querySelector('.upload').hidden=isCurated;
 showExpectedReference(job.expected_reference);configureAnnotatedExport();updateAskState();
}
